import{_ as r,a0 as i,w as m,s as n,I as p,x as t,a1 as e,A as s,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"怎樣設置Samba文件服務器以使用Windows客户端 | LCTT x X-CMD","titleTemplate":false,"description":"怎樣設置Samba文件服務器以使用Windows客户端 | LCTT (201408) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"怎樣設置Samba文件服務器以使用Windows客户端 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"怎樣設置Samba文件服務器以使用Windows客户端 | LCTT (201408) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201408/20140808 How to set up a Samba file server to use with Windows clients","title":"怎樣設置Samba文件服務器以使用Windows客户端","tag":"201408","desc":""},"relativePath":"201408/20140808 How to set up a Samba file server to use with Windows clients.md","filePath":"[post].md"}'),d={name:"201408/20140808 How to set up a Samba file server to use with Windows clients.md"};function c(b,a,f,u,g,h){const o=i("Link");return m(),n("div",null,[a[16]||(a[16]=p("h1",{id:"怎樣設置samba文件服務器以使用windows客户端",tabindex:"-1"},[t("怎樣設置Samba文件服務器以使用Windows客户端 "),p("a",{class:"header-anchor",href:"#怎樣設置samba文件服務器以使用windows客户端","aria-label":"Permalink to “怎樣設置Samba文件服務器以使用Windows客户端”"},"​")],-1)),p("p",null,[a[1]||(a[1]=t("根據",-1)),e(o,{href:"http://www.samba.org/"},{default:s(()=>[...a[0]||(a[0]=[t("Samba",-1)])]),_:1}),a[2]||(a[2]=t("項目網站所述，Samba是一個開源/自由軟件套件，提供了到SMB/CIFS客户端的無縫文件和打印服務。不同於其它SMB/CIFS網絡協議部署（如HP-UX的LM服務器，OS/2的LAN服務器，或者VisionFS），Samba（及其源代碼）是可以自由獲取的（終端用户無需付費），允許在Linux/Unixt服務器和Windows/Unix/Linux客户端之間互操作。",-1))]),a[17]||(a[17]=l(`<p>出於這些理由，Samba在不同操作系統（除了Linux）共存的網絡中首選的文件服務器解決方案——最常見的結構是多個微軟Windows客户端訪問安裝有Samba的Linux服務器，該情形也是本文將要解決的問題。</p><p>請注意，另外一方面，如果我們的網絡僅僅是由基於Unix的客户端（如Linux，AIX，或者Solaris，等等）組成，我們可以考慮使用NFS（儘管在此種情況下Samba仍然是可選方案），它可以提供更快的速度。</p><h3 id="在debian和centos中安裝samba" tabindex="-1">在Debian和CentOS中安裝Samba <a class="header-anchor" href="#在debian和centos中安裝samba" aria-label="Permalink to “在Debian和CentOS中安裝Samba”">​</a></h3><p>在我們開始安裝之前，我們可以使用操作系統中的包管理系統查詢Samba的信息：</p><p>在Debian上：</p><pre><code># aptitude show samba
</code></pre><p>在CentOS上：</p><pre><code># yum info samba
</code></pre><p>在下面的屏幕截圖中，我們可以看到‘aptitude show samba’的輸出（‘yum info samba’會產生類似的結果）：</p><p><img src="https://farm4.staticflickr.com/3868/14837993244_0fa525eb35_z.jpg" alt=""></p><p>現在讓我們來安裝Samba吧（下面的截圖來自Debian 7[Wheezy]服務器上的安裝）：</p><p>在Debian上：</p><pre><code># aptitude install samba
</code></pre><p>在CentOS上：</p><pre><code># yum install samba
</code></pre><h3 id="添加用户到samba" tabindex="-1">添加用户到Samba <a class="header-anchor" href="#添加用户到samba" aria-label="Permalink to “添加用户到Samba”">​</a></h3><p>對於4.x之前的版本，需要建立一個本地Unix帳號以便將其添加到Samba：</p><pre><code># adduser &lt;username&gt; 
</code></pre><p><img src="https://farm6.staticflickr.com/5574/14837266181_fed68bddf2_o.png" alt=""></p><p>接下來，我們需要添加用户到Samba，使用帶有‘-a’選項的smbpasswd命令來完成，該命令指出後面的用户名將被添加到本地smbpasswd文件中。我們將被提示輸入密碼（該密碼無需和本地Unix帳號的密碼相同）：</p><pre><code># smbpassword -a &lt;username&gt; 
</code></pre><p><img src="https://farm6.staticflickr.com/5555/14653711099_578f8613ca.jpg" alt=""></p><p>最後，我們將賦予用户xmodulo到我們系統上某個目錄的訪問權限，該目錄將被用於作為此用户的Samba共享（如有需要，也可以共享給其它用户）。要完成該工作，請使用文本編輯器（如Vim）打開/etc/samba/smb.conf文件，導航到文件末，然後創建一個帶有描述名稱的區塊（使用方括號將其括起來），如[xmodulo]：</p><pre><code># SAMBA SHARE
[xmodulo]
path = /home/xmodulo
available = yes
valid users = xmodulo
read only = no
browseable = yes
public = yes
writeable = yes
</code></pre><p>我們現在必須重啓Samba—以防萬一—使用testparm命令來檢查smb.conf文件的語法錯誤：</p><pre><code># service samba restart
# testparm 
</code></pre><p><img src="https://farm6.staticflickr.com/5589/14653655390_becb4f4981_z.jpg" alt=""></p><p>如果有錯誤，在testparm結束後會報告。</p><h3 id="在windows-7計算機上將samba共享映射為一個網絡驅動器" tabindex="-1">在Windows 7計算機上將Samba共享映射為一個網絡驅動器 <a class="header-anchor" href="#在windows-7計算機上將samba共享映射為一個網絡驅動器" aria-label="Permalink to “在Windows 7計算機上將Samba共享映射為一個網絡驅動器”">​</a></h3><p>在計算機上右擊，然後選擇“映射網絡驅動器”：</p><p><img src="https://farm6.staticflickr.com/5571/14837993154_981b73ea92.jpg" alt=""></p><p>輸入安裝了Samba的機器的IP地址，後跟共享名（就是smb.conf文件中方括號括起來的那個名稱），然後確保選中了“使用不同的憑據連接”：</p><p><img src="https://farm4.staticflickr.com/3881/14839997172_d67ec98933_o.png" alt=""></p><p>輸入先前用‘<strong>smbpasswd -a</strong>’設置的用户名和密碼：</p><p><img src="https://farm6.staticflickr.com/5563/14653711029_ddfea53bd6_o.png" alt=""></p><p>進入計算機，然後檢查網絡驅動器是否被正確添加：</p><p><img src="https://farm6.staticflickr.com/5584/14837993124_c664728039_o.png" alt=""></p><p>作為測試，讓我們從Samba的手冊頁創建一個pdf文件，然後保存到/home/xmodulo目錄：</p><p><img src="https://farm6.staticflickr.com/5593/14860219723_e8380f0d0f_o.png" alt=""></p><p>接下來，我們可以驗證該文件是否可以從Windows讀取：</p><p><img src="https://farm4.staticflickr.com/3869/14817386696_74a12dfdcd_o.png" alt=""></p><p>然後檢查我們是否能夠用默認的pdf閲讀器打開它：</p><p><img src="https://farm6.staticflickr.com/5584/14653655350_8a243b1493_z.jpg" alt=""></p><p>最後，讓我們看看我們是否能在Windows中剛剛映射的驅動器上保存文件。我們將打開change.log文件，該文件列出了Notepad++的功能：</p><p><img src="https://farm6.staticflickr.com/5565/14817386676_18c1d7bc60_o.png" alt=""></p><p>然後試着將它作為普通文本文件（.txt擴展名）保存到Z:\\；然後讓我們看看該文件是否能在Linux中看到：</p><p><img src="https://farm4.staticflickr.com/3841/14817386656_fb09a95a65_o.png" alt=""></p><h3 id="啓用磁盤配額" tabindex="-1">啓用磁盤配額 <a class="header-anchor" href="#啓用磁盤配額" aria-label="Permalink to “啓用磁盤配額”">​</a></h3><p>作為第一步，我們需要驗證當前內核是否已經編譯為支持配額：</p><pre><code># cat /boot/config-$(uname -r) | grep 
</code></pre><p><img src="https://farm4.staticflickr.com/3867/14837993054_081dc9b0dc_z.jpg" alt=""></p><p>每個文件系統最多有5種類型，能夠強制使用的配額限制：用户軟限制，用户硬限制，組軟限制，組硬限制，以及寬限期限。</p><p>我們現在將為/home文件系統啓用磁盤配額，在/etc/fstab文件對應的/home文件系統行現存的默認選項後添加usrquota和grpquto掛載選項，然後重新掛載文件系統以令修改生效：</p><p><img src="https://farm6.staticflickr.com/5561/14653806067_b8b0dc2333_z.jpg" alt=""></p><p>接下來，我們需要在<strong>/home</strong>目錄創建兩個文件以用於作為用户和組配額的資料庫文件：<strong>aquota.user</strong>和<strong>aquota.group</strong>。然後，我們將生成啓用配額後每個文件系統的當前磁盤使用表：</p><pre><code># quotacheck -cug /home
# quotacheck -avugm 
</code></pre><p><img src="https://farm6.staticflickr.com/5584/14837265971_654e8f3bc0_o.png" alt=""></p><p>儘管已經為/home文件系統啓用磁盤配額，我們還沒有給任何用户或組設置權限。檢查現有用户/組的配額信息：</p><pre><code># quota -u &lt;username&gt;
# quota -g &lt;groupname&gt; 
</code></pre><p><img src="https://farm6.staticflickr.com/5582/14653735848_8de88d69c4_o.png" alt=""></p><p>在這最後幾步中，使用quotatool命令來為每個用户和/或組來分配磁盤配額（注意，該任務也可以使用edquota來完成，但是quotatool更為直接，更不易犯錯）。</p><p>要為用户xmodulo設置軟限制為4MB，硬限制為5MB，xmodulo組為10MB/15MB：</p><pre><code># quotatool -u xmodulo -bq 4M -l &#39;5 Mb&#39; /home
# quotatool -g xmodulo -bq 10M -l &#39;15 Mb&#39; /home 
</code></pre><p><img src="https://farm4.staticflickr.com/3888/14653806037_5438b5034e_z.jpg" alt=""></p><p>我們可以在Windows 7中看到結果（4.00MB中有3.98MB空閒）：</p><p><img src="https://farm4.staticflickr.com/3919/14653805967_c2b1551869_o.png" alt=""></p><hr>`,67)),p("p",null,[a[4]||(a[4]=t("via: ",-1)),e(o,{href:"http://xmodulo.com/2014/08/samba-file-server-windows-clients.html"},{default:s(()=>[...a[3]||(a[3]=[t("http://xmodulo.com/2014/08/samba-file-server-windows-clients.html",-1)])]),_:1})]),p("p",null,[a[8]||(a[8]=t("作者：",-1)),e(o,{href:"http://xmodulo.com/author/gabriel"},{default:s(()=>[...a[5]||(a[5]=[t("Gabriel Cánepa",-1)])]),_:1}),a[9]||(a[9]=t(" 譯者：",-1)),e(o,{href:"https://github.com/GOLinux"},{default:s(()=>[...a[6]||(a[6]=[t("GOLinux",-1)])]),_:1}),a[10]||(a[10]=t(" 校對：",-1)),e(o,{href:"https://github.com/carolinewuyan"},{default:s(()=>[...a[7]||(a[7]=[t("Caroline",-1)])]),_:1})]),p("p",null,[a[13]||(a[13]=t("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...a[11]||(a[11]=[t("LCTT",-1)])]),_:1}),a[14]||(a[14]=t(" 原創翻譯，",-1)),e(o,{href:"http://linux.cn/"},{default:s(()=>[...a[12]||(a[12]=[t("Linux中國",-1)])]),_:1}),a[15]||(a[15]=t(" 榮譽推出",-1))])])}const x=r(d,[["render",c]]);export{_ as __pageData,x as default};
